@extends('layouts.app')@section('content')<h1>Your basket</h1>@if(!$cart)<div class="card"><h2>Cart is empty</h2><a class="btn" href="/products">Browse groceries</a></div>@else<div class="card">@foreach($cart as $i)<div class="row"><span><b>{{ $i['name'] }}</b><small>{{ $i['unit'] }} · ₹{{ number_format($i['price'],2) }} each</small></span><form method="post" action="/cart/update/{{ $i['id'] }}">@csrf<input class="qty" name="quantity" type="number" min="1" value="{{ $i['quantity'] }}"><button>Update</button></form><b>₹{{ number_format($i['price']*$i['quantity'],2) }}</b><form method="post" action="/cart/remove/{{ $i['id'] }}">@csrf<button>Remove</button></form></div>@endforeach<h2>Total ₹{{ number_format($total,2) }}</h2><a class="btn" href="/checkout">Checkout →</a></div>@endif@endsection